from typing import List

def separate_paren_groups(paren_string: str) -> List[str]:
    def extract_groups(paren_string):
        groups = []
        group = ''
        for char in paren_string:
            if char == '(':
                group += char
            elif char == ')':
                group += char
                groups.append(group)
                group = ''
        return groups

    def remove_spaces(groups):
        return [group.replace(' ', '') for group in groups]

    def split_groups(groups):
        return groups

    extracted_groups = extract_groups(paren_string)
    cleaned_groups = remove_spaces(extracted_groups)

    return cleaned_groups

